<template>
  <div class="workbench">
    <aside class="sidebar">
      <a class="brand" href="#/dashboard"><span class="brand-icon"><i></i><b></b></span><span>MediStock<small>药品进销存工作台</small></span></a>
      <div class="workspace"><span class="workspace-icon"><i class="el-icon-office-building"></i></span><div>桂林 · 中心药房<small>本地工作空间</small></div><i class="el-icon-arrow-down"></i></div>
      <p class="nav-caption">工作空间</p>
      <nav><router-link v-for="item in navigation" :key="item.key" :to="'/' + item.key" :aria-label="item.title" :title="item.title" :class="{ active: section === item.key }"><i :class="item.icon"></i><span>{{ item.title }}</span><em v-if="item.key === 'inventory' && alertCount">{{ alertCount }}</em></router-link></nav>
      <div class="sidebar-bottom"><div class="local-status"><span></span> {{ error ? '连接中断 · 请重新连接' : ready ? '数据已保存至本机' : '正在连接工作空间' }}</div><div class="profile"><span>宋</span><div>宋浩<small>工作台管理员</small></div><i class="el-icon-more"></i></div></div>
    </aside>
    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb">工作空间 <span>/</span> <b>{{ pageTitle }}</b></div><div class="top-actions"><button class="icon-button" title="刷新工作台" aria-label="刷新工作台" @click="refresh"><i class="el-icon-refresh"></i></button><button class="icon-button notification" title="查看库存提醒" aria-label="查看库存提醒" @click="goInventory('attention')"><i class="el-icon-bell"></i><span v-if="alertCount"></span></button><div class="avatar">宋</div></div></header>
      <main>
        <div v-if="error" class="error-banner"><i class="el-icon-warning-outline"></i>{{ error }}<el-button type="text" @click="refresh">重新连接</el-button></div>
        <div v-if="!ready && !error" class="initial-loading"><i class="el-icon-loading"></i><span>正在连接药房工作空间…</span></div>
        <template v-if="ready">
        <div class="page-heading"><div><p class="eyebrow">{{ section === 'dashboard' ? 'YOUR PHARMACY, AT A GLANCE' : 'MEDISTOCK WORKSPACE' }}</p><h1>{{ pageTitle }}<span v-if="section === 'dashboard'" class="greeting-dot"></span></h1><p class="subtitle">{{ pageSubtitle }}</p></div><div class="heading-actions"><span class="date-chip"><i class="el-icon-date"></i>{{ formattedDate }}</span><el-button v-if="section === 'dashboard'" type="primary" icon="el-icon-plus" @click="$router.push('/inbound')">新建入库</el-button><el-button v-if="section === 'medicines'" type="primary" icon="el-icon-plus" @click="editMedicine()">新增药品</el-button><el-button v-if="section === 'suppliers'" type="primary" icon="el-icon-plus" @click="editSupplier()">新增供应商</el-button></div></div>

        <template v-if="section === 'dashboard'">
          <section class="summary-banner"><div><span class="live-pill"><i></i> PHARMACY OVERVIEW</span><h2>库存有序，<span>每一份安心都有迹可循。</span></h2><p>{{ stats.types || 0 }} 种药品 · {{ data.batches.length }} 个批次 · 从入库到出库，全程可追溯</p><button @click="$router.push('/inventory')">查看全部库存 <i class="el-icon-top-right"></i></button></div><div class="medicine-art" aria-hidden="true"><div class="art-orbit"></div><div class="bottle"><div class="bottle-cap"></div><div class="bottle-label"><span>MEDI</span><i>+</i><small>CARE EVERY DAY</small></div></div><div class="pill-card"><div class="pill-shape"></div><div><b>库存健康管理</b><small>更清晰 · 更安心</small></div><i class="el-icon-check"></i></div><span class="art-dot"></span></div></section>
          <section class="metrics-grid"><article v-for="metric in metrics" :key="metric.label" class="metric-card"><div class="metric-top"><span>{{ metric.label }}</span><i :class="metric.icon" :style="{color:metric.color,background:metric.background}"></i></div><div class="metric-value">{{ metric.value }}<small>{{ metric.unit }}</small></div><div class="metric-footer"><span :class="metric.tone"><i :class="metric.footerIcon"></i>{{ metric.footer }}</span><span>{{ metric.detail }}</span></div></article></section>
          <section class="charts-grid"><article class="panel trend-panel"><div class="panel-heading"><div><h3>出入库趋势</h3><p>近 7 天的药品流转记录</p></div><span class="soft-tag">最近 7 天</span></div><div ref="trendChart" class="trend-chart" role="img" aria-label="最近七天真实单据出入库趋势图"></div><div class="chart-footnote"><i class="el-icon-info"></i>根据已提交单据实时统计，单位：件</div></article><article class="panel category-panel"><div class="panel-heading"><div><h3>库存构成</h3><p>按药品分类查看库存分布</p></div><i class="el-icon-pie-chart muted"></i></div><div class="donut-wrap"><div ref="categoryChart" class="category-chart" role="img" aria-label="药品库存分类占比图"></div><div class="donut-label"><b>{{ stats.types || 0 }}</b><span>药品种类</span></div></div><div class="category-legend"><div v-for="(cat, i) in data.categories" :key="cat.name"><span><i :style="{background:chartColors[i % chartColors.length]}"></i>{{ cat.name }}</span><b>{{ Math.round(cat.value / (stats.stock || 1) * 100) }}%</b></div></div></article></section>
          <section class="attention-grid"><article class="panel attention-panel"><div class="panel-heading"><div class="heading-inline"><span class="status-icon amber"><i class="el-icon-time"></i></span><div><h3>效期提醒 <em>{{ expiryAlerts.length }}</em></h3><p>优先处理临期及已过期批次</p></div></div><button class="text-button" @click="goInventory('attention')">查看全部 <i class="el-icon-arrow-right"></i></button></div><div v-if="!expiryAlerts.length" class="inline-empty">效期状态良好，暂无临期批次</div><div v-for="b in expiryAlerts.slice(0,3)" :key="b.id" class="attention-row"><span class="drug-icon" :class="b.expiryDate < data.today ? 'rose' : 'amber'"><i class="el-icon-first-aid-kit"></i></span><div><b>{{ b.name }}</b><small>{{ b.batchNo }} · {{ b.quantity }} {{ b.unit }}</small></div><span class="status-pill" :class="b.expiryDate < data.today ? 'danger' : 'warning'">{{ b.expiryDate < data.today ? '已过期 · 禁止出库' : '剩余 ' + remainingDays(b.expiryDate) + ' 天' }}</span></div></article><article class="panel attention-panel"><div class="panel-heading"><div class="heading-inline"><span class="status-icon blue"><i class="el-icon-box"></i></span><div><h3>补货建议 <em>{{ lowMedicines.length }}</em></h3><p>依据可用库存与预警线计算</p></div></div><button class="text-button" @click="$router.push('/inbound')">去补货 <i class="el-icon-arrow-right"></i></button></div><div v-if="!lowMedicines.length" class="inline-empty">库存充足，暂无补货需求</div><div v-for="m in lowMedicines.slice(0,3)" :key="m.id" class="attention-row"><span class="drug-icon blue"><i class="el-icon-first-aid-kit"></i></span><div><b>{{ m.name }}</b><small>建议补充 {{ Math.max(0, m.minStock * 2 - m.available) }} {{ m.unit }} · 预警线 {{ m.minStock }}</small></div><div class="stock-warning"><b>{{ m.available }}<small> {{ m.unit }}</small></b><span>可用库存偏低</span></div></div></article></section>
          <article class="panel"><div class="panel-heading"><div><h3>最近流转</h3><p>每一笔出入库，都有清晰的记录</p></div><button class="text-button" @click="$router.push('/history')">全部单据 <i class="el-icon-arrow-right"></i></button></div><el-table :data="data.documents.slice(0,5)" @row-click="showDocument"><el-table-column label="单据" min-width="210"><template slot-scope="s"><div class="doc-id"><span class="mini-arrow" :class="s.row.type"><i :class="s.row.type === 'inbound' ? 'el-icon-bottom-left' : 'el-icon-top-right'"></i></span><div><b>{{ s.row.type === 'inbound' ? '采购入库' : '领用出库' }}</b><small>{{ s.row.id }}</small></div></div></template></el-table-column><el-table-column label="药品名称" prop="name" min-width="150"/><el-table-column label="数量" width="115"><template slot-scope="s"><b :class="s.row.type === 'inbound' ? 'teal-text' : 'gray-text'">{{ s.row.type === 'inbound' ? '+' : '−' }}{{ s.row.quantity }} {{ s.row.unit }}</b></template></el-table-column><el-table-column label="往来单位" prop="party" min-width="170"/><el-table-column label="日期" prop="date" width="120"/><el-table-column label="状态" width="100"><template><span class="status-pill success">已完成</span></template></el-table-column></el-table></article>
        </template>

        <template v-if="section === 'inventory'">
          <section class="inventory-summary"><div><span class="status-icon teal"><i class="el-icon-box"></i></span><div><small>在库总量</small><b>{{ number(stats.stock) }}<em> 件</em></b></div></div><div><span class="status-icon blue"><i class="el-icon-first-aid-kit"></i></span><div><small>药品 / 批次</small><b>{{ stats.types }}<em> / {{ data.batches.length }}</em></b></div></div><div><span class="status-icon amber"><i class="el-icon-time"></i></span><div><small>90 天内临期</small><b>{{ stats.expiring }}<em> 个批次</em></b></div></div><div><span class="status-icon rose"><i class="el-icon-warning-outline"></i></span><div><small>过期隔离</small><b>{{ stats.expired }}<em> 个批次</em></b></div></div></section>
          <article class="panel"><div class="table-toolbar"><div class="segmented"><button v-for="f in inventoryFilters" :key="f.key" :class="{selected:inventoryFilter === f.key}" @click="inventoryFilter = f.key">{{ f.label }}</button></div><el-input v-model="search" prefix-icon="el-icon-search" placeholder="搜索药品、批号、库位" clearable class="search-input"/><el-button icon="el-icon-download" @click="exportInventory">导出 CSV</el-button></div><el-table :data="filteredBatches" empty-text="没有符合条件的批次"><el-table-column label="药品 / 规格" min-width="210"><template slot-scope="s"><div class="drug-name"><span class="drug-icon" :style="{background:categoryColor(s.row.category)+'15',color:categoryColor(s.row.category)}"><i class="el-icon-first-aid-kit"></i></span><div><b>{{ s.row.name }}</b><small>{{ s.row.spec }}</small></div></div></template></el-table-column><el-table-column label="批号" prop="batchNo" min-width="160"/><el-table-column label="效期" prop="expiryDate" width="115"/><el-table-column label="库存" width="90"><template slot-scope="s"><b>{{ s.row.quantity }}</b><span class="muted"> {{ s.row.unit }}</span></template></el-table-column><el-table-column label="库位" prop="location" width="85"/><el-table-column label="状态" min-width="135"><template slot-scope="s"><span class="status-pill" :class="batchStatus(s.row).class">{{ batchStatus(s.row).label }}</span></template></el-table-column><el-table-column label="供应商" prop="supplier" min-width="180"/></el-table><div class="table-footer">共 {{ filteredBatches.length }} 个批次 · 已过期批次自动隔离，出库按效期优先分配</div></article>
        </template>

        <template v-if="section === 'medicines'">
          <article class="panel"><div class="table-toolbar"><div><h3>药品档案</h3><p>维护名称、规格、库位与补货预警线</p></div><el-input v-model="search" prefix-icon="el-icon-search" placeholder="搜索药品名称 / 分类" clearable class="search-input"/></div><el-table :data="filteredMedicines" empty-text="暂无药品，点击右上角新增"><el-table-column label="药品 / 规格" min-width="225"><template slot-scope="s"><div class="drug-name"><span class="drug-icon teal"><i class="el-icon-first-aid-kit"></i></span><div><b>{{ s.row.name }}</b><small>{{ s.row.spec }}</small></div></div></template></el-table-column><el-table-column label="分类" prop="category" min-width="100"/><el-table-column label="参考单价" min-width="100"><template slot-scope="s">{{ money(s.row.priceCents) }}</template></el-table-column><el-table-column label="可用 / 在库" min-width="110"><template slot-scope="s"><b :class="s.row.available < s.row.minStock ? 'amber-text' : ''">{{ s.row.available }}</b> / {{ s.row.stock }} {{ s.row.unit }}</template></el-table-column><el-table-column label="预警线" prop="minStock" width="85"/><el-table-column label="库位" prop="location" width="85"/><el-table-column label="操作" min-width="125"><template slot-scope="s"><el-button type="text" @click="editMedicine(s.row)">编辑</el-button><el-button type="text" class="delete-button" @click="removeRecord('medicines',s.row)">删除</el-button></template></el-table-column></el-table></article>
        </template>

        <template v-if="section === 'suppliers'">
          <div class="supplier-grid"><article v-for="s in data.suppliers" :key="s.id" class="panel supplier-card"><span class="supplier-symbol"><i class="el-icon-office-building"></i></span><span class="status-pill success supplier-badge">合作档案</span><h3>{{ s.name }}</h3><p><i class="el-icon-location-outline"></i>{{ s.city || '未填写城市' }}</p><div class="supplier-detail"><div><small>联系人</small><b>{{ s.contact || '—' }}</b></div><div><small>联系电话</small><b>{{ s.phone || '—' }}</b></div></div><div class="supplier-footer"><span>{{ data.batches.filter(b=>b.supplierId === s.id).length }} 个关联批次</span><div><el-button type="text" @click="editSupplier(s)">编辑</el-button><el-button type="text" class="delete-button" @click="removeRecord('suppliers',s)">删除</el-button></div></div></article><button class="supplier-add" @click="editSupplier()"><i class="el-icon-plus"></i><b>添加新的供应伙伴</b><small>让每一批药品来源清晰</small></button></div>
        </template>

        <template v-if="section === 'inbound' || section === 'outbound'">
          <div class="transaction-layout"><article class="panel transaction-form"><div class="panel-heading"><div class="heading-inline"><span class="status-icon" :class="section === 'inbound' ? 'teal' : 'blue'"><i :class="section === 'inbound' ? 'el-icon-bottom-left' : 'el-icon-top-right'"></i></span><div><h3>{{ section === 'inbound' ? '采购入库单' : '领用出库单' }}</h3><p>提交后同步更新批次库存与单据账本</p></div></div><span class="soft-tag">{{ data.today }}</span></div><el-form :model="transaction" label-position="top" @submit.native.prevent="submitTransaction"><el-form-item label="选择药品 *"><el-select v-model="transaction.medicineId" filterable placeholder="搜索并选择药品" class="full-width"><el-option v-for="m in data.medicines" :key="m.id" :label="m.name + ' · ' + m.spec" :value="m.id"/></el-select></el-form-item><div class="form-row"><el-form-item :label="'数量' + (selectedMedicine ? '（' + selectedMedicine.unit + '）' : '') + ' *'"><el-input-number v-model="transaction.quantity" :min="1" :max="1000000" :precision="0" controls-position="right" class="full-width"/></el-form-item><el-form-item label="往来单位 / 领用科室 *"><el-input v-model="transaction.party" maxlength="80" placeholder="例如：门诊药房"/></el-form-item></div><template v-if="section === 'inbound'"><div class="form-row"><el-form-item label="生产批号 *"><el-input v-model="transaction.batchNo" maxlength="50" placeholder="例如 GL-2026-010"/></el-form-item><el-form-item label="有效期至 *"><el-date-picker v-model="transaction.expiryDate" type="date" value-format="yyyy-MM-dd" placeholder="选择有效期" class="full-width"/></el-form-item></div><el-form-item label="供应商 *"><el-select v-model="transaction.supplierId" placeholder="选择供应商" class="full-width"><el-option v-for="s in data.suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></template><el-form-item label="备注"><el-input v-model="transaction.note" type="textarea" :rows="3" maxlength="200" show-word-limit placeholder="补充用途、验收或批次说明（可选）"/></el-form-item><div v-if="submitError" class="form-error"><i class="el-icon-warning-outline"></i>{{ submitError }}</div><div class="submit-row"><span><i class="el-icon-lock"></i>本机事务保存 · 防止重复提交</span><el-button type="primary" native-type="submit" :loading="busy" icon="el-icon-check">确认{{ section === 'inbound' ? '入库' : '出库' }}</el-button></div></el-form></article><div class="transaction-aside"><article class="panel preview-card"><span class="eyebrow">{{ section === 'outbound' ? 'FEFO ALLOCATION' : 'BATCH PREVIEW' }}</span><h3>{{ section === 'outbound' ? '效期优先，自动分配' : '批次信息，一目了然' }}</h3><p>{{ section === 'outbound' ? '先使用效期最近的可用批次。已过期库存不会参与出库。' : '同一药品的相同批号会合并库存。效期或供应商冲突会被拒绝。' }}</p><template v-if="selectedMedicine"><div class="preview-medicine"><span class="drug-icon teal"><i class="el-icon-first-aid-kit"></i></span><div><b>{{ selectedMedicine.name }}</b><small>{{ selectedMedicine.spec }}</small></div></div><div class="preview-totals"><div><small>当前可用</small><b>{{ selectedMedicine.available }}<em> {{ selectedMedicine.unit }}</em></b></div><div><small>参考金额</small><b>{{ money(selectedMedicine.priceCents * transaction.quantity) }}</b></div></div><template v-if="section === 'outbound'"><div v-for="p in allocationPreview" :key="p.id" class="allocation-line"><div><b>{{ p.batchNo }}</b><small>效期 {{ p.expiryDate }}</small></div><strong>−{{ p.take }}</strong></div><div v-if="availableShortage" class="form-error">缺少 {{ availableShortage }} {{ selectedMedicine.unit }} 可用库存，请调整数量。</div><div v-if="!allocationPreview.length" class="inline-empty">暂无可用批次</div></template></template><div v-else class="preview-empty"><i class="el-icon-first-aid-kit"></i><span>选择药品，查看库存与分配</span></div></article><article class="help-card"><i class="el-icon-circle-check"></i><div><h4>每次操作，都留有依据</h4><p>单据创建与库存变化在同一事务完成；提交失败不会扣减库存。</p></div></article></div></div>
        </template>

        <template v-if="section === 'history'"><article class="panel"><div class="table-toolbar"><div class="segmented"><button v-for="f in [{key:'all',label:'全部单据'},{key:'inbound',label:'采购入库'},{key:'outbound',label:'领用出库'}]" :key="f.key" :class="{selected:historyFilter===f.key}" @click="historyFilter=f.key">{{ f.label }}</button></div><el-input v-model="search" prefix-icon="el-icon-search" placeholder="搜索药品、单据、往来单位" clearable class="search-input"/></div><el-table :data="filteredDocuments" @row-click="showDocument" empty-text="没有符合条件的单据"><el-table-column label="单据编号" prop="id" min-width="245"/><el-table-column label="类型" width="100"><template slot-scope="s"><span class="status-pill" :class="s.row.type==='inbound'?'success':'info'">{{ s.row.type==='inbound'?'采购入库':'领用出库' }}</span></template></el-table-column><el-table-column label="药品" prop="name" min-width="150"/><el-table-column label="数量" width="100"><template slot-scope="s">{{ s.row.quantity }} {{ s.row.unit }}</template></el-table-column><el-table-column label="往来单位" prop="party" min-width="160"/><el-table-column label="日期" prop="date" width="115"/><el-table-column label="详情" width="80"><template slot-scope="s"><el-button type="text" @click.stop="showDocument(s.row)">追溯 <i class="el-icon-arrow-right"></i></el-button></template></el-table-column></el-table><div class="table-footer">共 {{ filteredDocuments.length }} 笔单据 · 点击单据查看批次分配与流转详情</div></article></template>

        <template v-if="section === 'settings'"><div class="settings-grid"><article class="panel settings-card"><span class="status-icon teal large"><i class="el-icon-folder-opened"></i></span><h3>数据由你掌握</h3><p>完整备份药品、供应商、批次和单据。数据保存在当前电脑，刷新或关闭浏览器后仍然保留。</p><div class="backup-stats"><div><b>{{ data.medicines.length }}</b><span>药品档案</span></div><div><b>{{ data.batches.length }}</b><span>库存批次</span></div><div><b>{{ data.documents.length }}</b><span>流转单据</span></div></div><el-button type="primary" icon="el-icon-download" @click="exportBackup">导出完整 JSON 备份</el-button></article><article class="panel settings-card"><span class="status-icon blue large"><i class="el-icon-upload2"></i></span><h3>恢复备份</h3><p>选择之前导出的完整备份。恢复前会验证结构、关联、单据数量与库存账本一致性。</p><div class="restore-tip"><i class="el-icon-info"></i>恢复会替换当前工作空间数据，请先导出备份。旧版 localStorage 文件不能直接导入。</div><input ref="backupFile" type="file" accept=".json,application/json" class="hidden-input" @change="importBackup"><el-button icon="el-icon-upload2" :loading="busy" @click="$refs.backupFile.click()">选择 JSON 备份</el-button><p v-if="restoreMessage" class="restore-message">{{ restoreMessage }}</p></article><article class="panel about-card"><div><span class="eyebrow">MEDISTOCK · PROJECT EDITION</span><h3>从课程实践，走向完整的药房工作流。</h3><p>Vue 2.7 · Element UI · Vuex · ECharts · Node.js · SQLite<br>单机展示版，不处理真实患者数据；初始记录均为演示数据。</p></div><span class="about-mark">+</span></article></div></template>

        <footer class="page-footer"><span>MediStock <b>·</b> 让每一份库存，都清晰可见。</span><span><i :class="error ? 'el-icon-warning-outline' : 'el-icon-circle-check'"></i> {{ error ? '连接中断 · 当前显示最后同步数据' : '本地数据库已连接' }}</span></footer>
        </template>
      </main>
    </div>
    <el-dialog :title="editingMedicine.id ? '编辑药品档案' : '新增药品档案'" :visible.sync="medicineDialog" width="560px" :close-on-click-modal="false"><el-form :model="editingMedicine" label-position="top"><div class="form-row"><el-form-item label="药品名称 *"><el-input v-model="editingMedicine.name" maxlength="60"/></el-form-item><el-form-item label="规格 *"><el-input v-model="editingMedicine.spec" maxlength="60"/></el-form-item></div><div class="form-row"><el-form-item label="分类 *"><el-select v-model="editingMedicine.category" filterable allow-create default-first-option class="full-width"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></el-form-item><el-form-item label="单位 *"><el-input v-model="editingMedicine.unit" maxlength="12"/></el-form-item></div><div class="form-row"><el-form-item label="参考单价（元） *"><el-input-number v-model="editingMedicine.price" :min="0" :max="10000" :precision="2" class="full-width" controls-position="right"/></el-form-item><el-form-item label="补货预警线 *"><el-input-number v-model="editingMedicine.minStock" :min="0" :max="1000000" :precision="0" class="full-width" controls-position="right"/></el-form-item></div><el-form-item label="库位 *"><el-input v-model="editingMedicine.location" placeholder="例如 A-01" maxlength="30"/></el-form-item><div v-if="dialogError" class="form-error">{{ dialogError }}</div></el-form><span slot="footer"><el-button @click="medicineDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveMedicine">保存档案</el-button></span></el-dialog>
    <el-dialog :title="editingSupplier.id ? '编辑供应商' : '新增供应商'" :visible.sync="supplierDialog" width="520px" :close-on-click-modal="false"><el-form :model="editingSupplier" label-position="top"><el-form-item label="供应商名称 *"><el-input v-model="editingSupplier.name" maxlength="80"/></el-form-item><div class="form-row"><el-form-item label="联系人"><el-input v-model="editingSupplier.contact" maxlength="30"/></el-form-item><el-form-item label="联系电话"><el-input v-model="editingSupplier.phone" maxlength="30"/></el-form-item></div><el-form-item label="所在城市"><el-input v-model="editingSupplier.city" maxlength="30"/></el-form-item><div v-if="dialogError" class="form-error">{{ dialogError }}</div></el-form><span slot="footer"><el-button @click="supplierDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveSupplier">保存档案</el-button></span></el-dialog>
    <el-dialog title="单据追溯" :visible.sync="documentDialog" width="620px"><template v-if="activeDocument"><div class="document-hero"><span class="status-icon teal large"><i :class="activeDocument.type==='inbound'?'el-icon-bottom-left':'el-icon-top-right'"></i></span><div><h3>{{ activeDocument.name }}</h3><p>{{ activeDocument.id }}</p></div><span class="status-pill success">已完成</span></div><div class="document-facts"><div><small>流转类型</small><b>{{ activeDocument.type==='inbound'?'采购入库':'领用出库' }}</b></div><div><small>数量</small><b>{{ activeDocument.quantity }} {{ activeDocument.unit }}</b></div><div><small>日期</small><b>{{ activeDocument.date }}</b></div><div><small>往来单位</small><b>{{ activeDocument.party }}</b></div></div><h4>批次明细</h4><el-table :data="activeDocument.lines"><el-table-column label="批号" prop="batchNo"/><el-table-column label="效期" prop="expiryDate"/><el-table-column label="数量" prop="quantity" width="100"/></el-table><p class="document-note">备注：{{ activeDocument.note || '无' }}</p></template></el-dialog>
  </div>
</template>

<script>
import * as echarts from 'echarts/core'
import { LineChart, PieChart } from 'echarts/charts'
import { GridComponent, TooltipComponent, LegendComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { request } from './api'
echarts.use([LineChart, PieChart, GridComponent, TooltipComponent, LegendComponent, CanvasRenderer])
const nav = [
  { key:'dashboard',title:'工作台概览',icon:'el-icon-data-analysis' },{ key:'inventory',title:'库存与效期',icon:'el-icon-box' },{ key:'medicines',title:'药品档案',icon:'el-icon-first-aid-kit' },{ key:'suppliers',title:'供应商',icon:'el-icon-office-building' },{ key:'inbound',title:'采购入库',icon:'el-icon-bottom-left' },{ key:'outbound',title:'领用出库',icon:'el-icon-top-right' },{ key:'history',title:'流转单据',icon:'el-icon-document' },{ key:'settings',title:'数据与备份',icon:'el-icon-setting' }
]
const colors = ['#20796e','#73a69b','#a9c4b9','#c0ae8b','#637c99']
const blankTransaction = (type) => ({ medicineId:null,quantity:10,party:type==='inbound'?'':'门诊药房',batchNo:'',expiryDate:'',supplierId:null,note:'',idempotencyKey:crypto.randomUUID() })
export default {
  data() { return {navigation:nav,chartColors:colors,search:'',inventoryFilter:'all',historyFilter:'all',inventoryFilters:[{key:'all',label:'全部库存'},{key:'attention',label:'需要关注'},{key:'available',label:'可用批次'},{key:'expired',label:'过期隔离'}],transaction:blankTransaction(),submitError:'',dialogError:'',busy:false,medicineDialog:false,supplierDialog:false,documentDialog:false,editingMedicine:{},editingSupplier:{},activeDocument:null,restoreMessage:'',charts:[] } },
  computed: {
    data(){return this.$store.state.snapshot},stats(){return this.data.stats},ready(){return this.$store.state.ready},error(){return this.$store.state.error},section(){return this.$route.path.slice(1)||'dashboard'},pageTitle(){return (nav.find(n=>n.key===this.section)||nav[0]).title},
    pageSubtitle(){return ({dashboard:'今天，也让药房运转得从容有序。',inventory:'掌握每一个批次，让临期与缺货都有准备。',medicines:'让药品信息清晰、统一，并与库存实时关联。',suppliers:'连接可靠的供应伙伴，追溯每一批药品来源。',inbound:'从采购到上架，完整记录每一批药品。',outbound:'按效期优先分配，让药品安全、有序流转。',history:'每一笔变化都有迹可循，每一个批次都可追溯。',settings:'完整备份，可靠恢复。你的数据始终由你掌握。'})[this.section]},
    formattedDate(){return this.data.today ? this.data.today.replace(/-/g,'.') : ''},
    categories(){return [...new Set(['抗感染','解热镇痛','营养补充','抗过敏','消化系统',...this.data.medicines.map(m=>m.category)])]},
    expiryAlerts(){return this.data.batches.filter(b=>b.quantity>0&&this.remainingDays(b.expiryDate)<=90)},lowMedicines(){return this.data.medicines.filter(m=>m.available<m.minStock)},alertCount(){return this.expiryAlerts.length+this.lowMedicines.length},
    metrics(){return [
      {label:'在库药品总量',value:this.number(this.stats.stock),unit:'件',icon:'el-icon-box',color:'#247b70',background:'#eaf5ef',tone:'teal-text',footerIcon:'el-icon-circle-check',footer:'实时库存',detail:this.stats.types+' 种药品'},
      {label:'库存参考价值',value:this.money(this.stats.valueCents),unit:'',icon:'el-icon-coin',color:'#667b9b',background:'#edf1f8',tone:'gray-text',footerIcon:'el-icon-data-line',footer:'按档案单价',detail:'非财务结算'},
      {label:'今日入库 / 出库',value:(this.stats.todayInbound||0)+' / '+(this.stats.todayOutbound||0),unit:'件',icon:'el-icon-sort',color:'#987b4b',background:'#f7f2e7',tone:'teal-text',footerIcon:'el-icon-document',footer:'单据已同步',detail:(this.stats.documents||0)+' 笔记录'},
      {label:'需要关注',value:this.alertCount,unit:'项',icon:'el-icon-bell',color:'#b17c42',background:'#fcf2e8',tone:'amber-text',footerIcon:'el-icon-time',footer:'效期 '+this.expiryAlerts.length+' · 补货 '+this.lowMedicines.length,detail:'及时处理'}
    ]},
    filteredBatches(){let list=this.data.batches.filter(b=>`${b.name} ${b.batchNo} ${b.location}`.toLowerCase().includes(this.search.toLowerCase()));if(this.inventoryFilter==='attention')list=list.filter(b=>b.quantity>0&&(this.remainingDays(b.expiryDate)<=90||this.lowMedicines.some(m=>m.id===b.medicineId)));if(this.inventoryFilter==='available')list=list.filter(b=>b.quantity>0&&b.expiryDate>=this.data.today);if(this.inventoryFilter==='expired')list=list.filter(b=>b.quantity>0&&b.expiryDate<this.data.today);return list},
    filteredMedicines(){return this.data.medicines.filter(m=>`${m.name} ${m.spec} ${m.category}`.toLowerCase().includes(this.search.toLowerCase()))},
    filteredDocuments(){return this.data.documents.filter(d=>(this.historyFilter==='all'||d.type===this.historyFilter)&&`${d.id} ${d.name} ${d.party}`.toLowerCase().includes(this.search.toLowerCase()))},
    selectedMedicine(){return this.data.medicines.find(m=>m.id===this.transaction.medicineId)},
    allocationPreview(){let remaining=this.transaction.quantity||0;return this.data.batches.filter(b=>b.medicineId===this.transaction.medicineId&&b.quantity>0&&b.expiryDate>=this.data.today).sort((a,b)=>a.expiryDate.localeCompare(b.expiryDate)||a.id-b.id).map(b=>{const take=Math.min(remaining,b.quantity);remaining-=take;return {...b,take}}).filter(b=>b.take>0)},
    availableShortage(){return Math.max(0,(this.transaction.quantity||0)-(this.selectedMedicine?this.selectedMedicine.available:0))}
  },
  watch:{section(){this.search='';this.submitError='';this.transaction=blankTransaction(this.section);this.$nextTick(this.renderCharts)},data(){this.$nextTick(this.renderCharts)},'transaction.supplierId'(id){if(this.section==='inbound'){const supplier=this.data.suppliers.find(s=>s.id===id);if(supplier)this.transaction.party=supplier.name}}},
  async mounted(){this.transaction=blankTransaction(this.section);window.addEventListener('resize',this.resizeCharts);await this.refresh()},
  beforeDestroy(){window.removeEventListener('resize',this.resizeCharts);this.disposeCharts()},
  methods:{
    number(n){return Number(n||0).toLocaleString('zh-CN')},money(cents){return '¥'+(Number(cents||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})},
    remainingDays(value){return Math.ceil((Date.parse(value)-Date.parse(this.data.today||new Date().toISOString().slice(0,10)))/86400000)},
    categoryColor(c){return colors[Math.max(0,this.categories.indexOf(c))%colors.length]},
    batchStatus(b){if(!b.quantity)return {class:'neutral',label:'已用尽'};if(b.expiryDate<this.data.today)return {class:'danger',label:'已过期 · 隔离'};if(this.remainingDays(b.expiryDate)<=90)return {class:'warning',label:'临期 '+this.remainingDays(b.expiryDate)+' 天'};return {class:'success',label:'库存正常'}},
    async refresh(){try{await this.$store.dispatch('refresh')}catch(e){this.$message.error(e.message)}},
    goInventory(filter){this.inventoryFilter=filter;this.$router.push('/inventory').catch(()=>{})},
    disposeCharts(){this.charts.forEach(c=>c.dispose());this.charts=[]},resizeCharts(){this.charts.forEach(c=>c.resize())},
    renderCharts(){this.disposeCharts();if(this.section!=='dashboard'||!this.$refs.trendChart)return;const trend=echarts.init(this.$refs.trendChart),category=echarts.init(this.$refs.categoryChart);this.charts=[trend,category];trend.setOption({color:['#237c70','#abc5bc'],tooltip:{trigger:'axis',backgroundColor:'#fff',borderColor:'#e8ecea',textStyle:{color:'#27382f'}},legend:{right:14,top:0,itemWidth:12,itemHeight:4,textStyle:{fontSize:11,color:'#7c8783'},data:['入库','出库']},grid:{top:45,left:50,right:20,bottom:25},xAxis:{type:'category',boundaryGap:false,data:this.data.trend.map(t=>t.date.slice(5).replace('-','/')),axisLine:{lineStyle:{color:'#e9ecea'}},axisTick:{show:false},axisLabel:{color:'#929a96',fontSize:11,margin:13}},yAxis:{type:'value',splitNumber:3,axisLabel:{color:'#929a96',fontSize:11},splitLine:{lineStyle:{color:'#eff1ef',type:'dashed'}}},series:[{name:'入库',type:'line',smooth:.35,symbol:'circle',symbolSize:6,lineStyle:{width:2.5},itemStyle:{borderWidth:2,borderColor:'#fff'},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'rgba(35,124,112,.17)'},{offset:1,color:'rgba(35,124,112,0)'}])},data:this.data.trend.map(t=>t.inbound)},{name:'出库',type:'line',smooth:.35,symbol:'circle',symbolSize:5,lineStyle:{width:2,type:'dashed'},data:this.data.trend.map(t=>t.outbound)}]});category.setOption({color:colors,tooltip:{trigger:'item',formatter:'{b}：{c} 件（{d}%）'},series:[{type:'pie',radius:['72%','94%'],center:['50%','50%'],label:{show:false},labelLine:{show:false},itemStyle:{borderColor:'#fff',borderWidth:4,borderRadius:7},data:this.data.categories}]})},
    editMedicine(m){this.editingMedicine=m?{...m,price:m.priceCents/100}:{name:'',spec:'',category:'抗感染',unit:'盒',minStock:30,price:0,location:''};this.dialogError='';this.medicineDialog=true},
    editSupplier(s){this.editingSupplier=s?{...s}:{name:'',contact:'',phone:'',city:''};this.dialogError='';this.supplierDialog=true},
    async saveMedicine(){this.busy=true;this.dialogError='';try{const m=this.editingMedicine;await request('/medicines'+(m.id?'/'+m.id:''),{method:m.id?'PUT':'POST',body:JSON.stringify({...m,priceCents:Math.round(m.price*100)})});await this.refresh();this.medicineDialog=false;this.$message.success('药品档案已保存')}catch(e){this.dialogError=e.message}finally{this.busy=false}},
    async saveSupplier(){this.busy=true;this.dialogError='';try{const s=this.editingSupplier;await request('/suppliers'+(s.id?'/'+s.id:''),{method:s.id?'PUT':'POST',body:JSON.stringify(s)});await this.refresh();this.supplierDialog=false;this.$message.success('供应商档案已保存')}catch(e){this.dialogError=e.message}finally{this.busy=false}},
    async removeRecord(kind,row){try{await this.$confirm(`确认删除“${row.name}”？存在库存或单据关联的档案将被保留。`,'删除档案',{confirmButtonText:'确认删除',cancelButtonText:'取消',type:'warning'});await request('/'+kind+'/'+row.id,{method:'DELETE'});await this.refresh();this.$message.success('档案已删除')}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(e.message)}},
    async submitTransaction(){if(this.busy)return;this.busy=true;this.submitError='';try{if(!this.transaction.medicineId)throw new Error('请先选择药品');if(!this.transaction.party.trim())throw new Error('请填写往来单位或领用科室');if(this.section==='outbound'&&this.availableShortage)throw new Error('可用库存不足，请调整数量');const result=await request('/'+this.section,{method:'POST',body:JSON.stringify(this.transaction)});await this.refresh();this.$message.success((result.duplicate?'单据已提交，未重复扣减':'单据已完成')+' · '+result.id);this.transaction=blankTransaction(this.section)}catch(e){this.submitError=e.message}finally{this.busy=false}},
    showDocument(row){this.activeDocument=row;this.documentDialog=true},
    download(text,name,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},
    exportInventory(){const escape=v=>'"'+String(v).replace(/"/g,'""')+'"';const rows=[['药品','规格','批号','有效期','数量','单位','库位','供应商'],...this.filteredBatches.map(b=>[b.name,b.spec,b.batchNo,b.expiryDate,b.quantity,b.unit,b.location,b.supplier])];this.download('\ufeff'+rows.map(r=>r.map(escape).join(',')).join('\r\n'),'MediStock_库存_'+this.data.today+'.csv','text/csv;charset=utf-8')},
    async exportBackup(){try{const backup=await request('/backup');this.download(JSON.stringify(backup,null,2),'MediStock_完整备份_'+this.data.today+'.json','application/json')}catch(e){this.$message.error(e.message)}},
    async importBackup(event){const file=event.target.files[0];event.target.value='';if(!file)return;this.restoreMessage='';try{if(file.size>5*1024*1024)throw new Error('备份不能超过 5 MB');const backup=JSON.parse(await file.text());await this.$confirm('恢复将替换当前数据。请确认你已导出需要保留的数据。','恢复完整备份',{confirmButtonText:'确认恢复',cancelButtonText:'取消',type:'warning'});this.busy=true;const result=await request('/restore',{method:'POST',body:JSON.stringify(backup)});await this.refresh();this.restoreMessage=`已恢复 ${result.medicines} 种药品、${result.documents} 笔单据。`;this.$message.success('备份恢复完成')}catch(e){if(e!=='cancel'&&e!=='close'){this.restoreMessage=e.message||'JSON 解析失败';this.$message.error(this.restoreMessage)}}finally{this.busy=false}}
  }
}
</script>
